/*
 * O modal "Histórico" do Discourse: uma revisão por vez, com ‹ › para andar
 * entre elas, quem editou e quando, e a comparação com a versão anterior —
 * no texto corrido (inline) ou lado a lado.
 *
 * Compara o texto-fonte (o markdown que foi digitado), que é o que o servidor
 * guarda: o HTML renderizado muda com extensões e configurações, e um diff
 * dele mostraria mudanças que ninguém fez.
 */
import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import { t } from '../../../utils/settings';
import { fullDate } from '../../../utils/dates';
import { diffStats, diffWords } from './diff';
const MODE_KEY = 'canela.historyMode';
function storedMode() {
  try {
    return localStorage.getItem(MODE_KEY) === 'side' ? 'side' : 'inline';
  } catch {
    return 'inline';
  }
}
export default class HistoryModal extends Modal {
  versions = [];
  contentHidden = false;
  /** A versão mostrada (índice em `versions`); a comparação é com a anterior. */
  index = 0;
  mode = storedMode();
  failed = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.loading = true;
    this.load().then(list => {
      this.versions = list.versions;
      this.contentHidden = list.contentHidden;
      // Abre na edição mais recente, como o Discourse.
      this.index = Math.max(0, this.versions.length - 1);
    }).catch(() => {
      this.failed = true;
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }

  /**
   * As versões da mais antiga para a mais nova. Separado do oninit para que
   * outro histórico (o das revisões da wiki) use o mesmo modal com os dados
   * dele.
   */
  load() {
    const apiUrl = String(app.forum.attribute('apiUrl') || '/api').replace(/\/+$/, '');
    const post = this.attrs.post;
    return app.request({
      method: 'GET',
      url: `${apiUrl}/canela/posts/${post.id()}/revisions`
    }).then(response => response.data);
  }
  className() {
    return 'CanelaHistoryModal Modal--large';
  }
  title() {
    return t('extras.history.title');
  }
  content() {
    if (this.loading) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, null));
    if (this.failed || !this.versions.length) {
      return m("div", {
        className: "Modal-body"
      }, m("p", {
        className: "CanelaHistory-empty"
      }, t('extras.history.failed')));
    }
    return m("div", {
      className: "Modal-body CanelaHistory"
    }, this.navigation(), this.contentHidden ? m("p", {
      className: "CanelaHistory-empty"
    }, t('extras.history.content_hidden')) : this.comparison());
  }
  navigation() {
    const last = this.versions.length - 1;
    const current = this.versions[this.index];
    const previous = this.index > 0 ? this.versions[this.index - 1] : null;
    const go = index => () => this.index = Math.min(last, Math.max(0, index));
    return m("div", {
      className: "CanelaHistory-nav"
    }, m("div", {
      className: "CanelaHistory-pager",
      role: "group",
      "aria-label": t('extras.history.pager_label')
    }, m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-backward-fast",
      disabled: this.index === 0,
      "aria-label": t('extras.history.first'),
      onclick: go(0)
    }), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-chevron-left",
      disabled: this.index === 0,
      "aria-label": t('extras.history.previous'),
      onclick: go(this.index - 1)
    }), m("span", {
      className: "CanelaHistory-position",
      "aria-live": "polite"
    }, previous ? t('extras.history.position', {
      from: previous.number,
      to: current.number,
      total: this.versions.length
    }) : t('extras.history.original', {
      total: this.versions.length
    })), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-chevron-right",
      disabled: this.index === last,
      "aria-label": t('extras.history.next'),
      onclick: go(this.index + 1)
    }), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-forward-fast",
      disabled: this.index === last,
      "aria-label": t('extras.history.last'),
      onclick: go(last)
    })), m("div", {
      className: "CanelaHistory-editor"
    }, current.user?.avatarUrl ? m("img", {
      className: "Avatar CanelaHistory-avatar",
      src: current.user.avatarUrl,
      alt: "",
      loading: "lazy"
    }) : m(Icon, {
      name: "fas fa-user-pen"
    }), m("span", null, t(previous ? 'extras.history.edited_by' : 'extras.history.created_by', {
      name: current.user ? current.user.displayName : t('extras.history.deleted_user'),
      date: current.createdAt ? fullDate(new Date(current.createdAt)) : ''
    }))), m("div", {
      className: "CanelaHistory-modes",
      role: "radiogroup",
      "aria-label": t('extras.history.mode_label')
    }, ['inline', 'side'].map(mode => m(Button, {
      className: classList('Button CanelaHistory-mode', {
        active: this.mode === mode
      }),
      icon: mode === 'inline' ? 'fas fa-align-left' : 'fas fa-table-columns',
      role: "radio",
      "aria-checked": this.mode === mode ? 'true' : 'false',
      onclick: () => this.setMode(mode)
    }, t(`extras.history.mode_${mode}`)))));
  }
  comparison() {
    const current = this.versions[this.index];
    const previous = this.index > 0 ? this.versions[this.index - 1] : null;

    // A versão original não tem com o que comparar: mostra o texto inteiro.
    if (!previous) {
      return m("pre", {
        className: "CanelaHistory-text"
      }, current.content || '');
    }
    const parts = diffWords(previous.content || '', current.content || '');
    const stats = diffStats(parts);
    return m("div", {
      className: "CanelaHistory-diff"
    }, m("div", {
      className: "CanelaHistory-stats"
    }, m("span", {
      className: "CanelaHistory-added"
    }, t('extras.history.added', {
      count: stats.added
    })), m("span", {
      className: "CanelaHistory-removed"
    }, t('extras.history.removed', {
      count: stats.removed
    }))), this.mode === 'inline' ? m("pre", {
      className: "CanelaHistory-text"
    }, this.render(parts, ['equal', 'insert', 'delete'])) : m("div", {
      className: "CanelaHistory-columns"
    }, m("pre", {
      className: "CanelaHistory-text CanelaHistory-text--before",
      "aria-label": t('extras.history.before')
    }, this.render(parts, ['equal', 'delete'])), m("pre", {
      className: "CanelaHistory-text CanelaHistory-text--after",
      "aria-label": t('extras.history.after')
    }, this.render(parts, ['equal', 'insert']))));
  }

  /** Só as partes dos tipos pedidos; <ins>/<del> dão o sentido também ao leitor de tela. */
  render(parts, kinds) {
    return parts.filter(part => kinds.includes(part.kind)).map(part => {
      if (part.kind === 'insert') return m("ins", {
        className: "CanelaHistory-ins"
      }, part.text);
      if (part.kind === 'delete') return m("del", {
        className: "CanelaHistory-del"
      }, part.text);
      return part.text;
    });
  }
  setMode(mode) {
    this.mode = mode;
    try {
      localStorage.setItem(MODE_KEY, mode);
    } catch {
      // Sem armazenamento, o modo vale só até fechar o modal.
    }
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/extras/history/HistoryModal', HistoryModal);